// Mollie embeds subscriptions under _embedded.subscriptions
const payload = items[0].json;
const subs = (payload._embedded && payload._embedded.subscriptions) || [];
let mrr_eur = 0;
let active_count = 0;
const byTier = { Lite: 0, Pro: 0, Max: 0 };
for (const s of subs) {
  if (s.status !== 'active') continue;
  const amt = parseFloat(s.amount?.value || '0');
  const interval = (s.interval || '').toLowerCase();
  let monthlyValue = 0;
  if (interval.includes('1 month')) monthlyValue = amt;
  else if (interval.includes('3 month')) monthlyValue = amt / 3;
  else if (interval.includes('6 month')) monthlyValue = amt / 6;
  else if (interval.includes('12 month') || interval.includes('1 year')) monthlyValue = amt / 12;
  else monthlyValue = amt; // unknown -> treat monthly
  mrr_eur += monthlyValue;
  active_count += 1;
  const tier = (s.metadata && s.metadata.tier) || 'Pro';
  if (byTier[tier] !== undefined) byTier[tier] += monthlyValue;
}
return [{
  json: {
    snapshot_date: new Date().toISOString().slice(0, 10),
    mrr_eur: Math.round(mrr_eur * 100) / 100,
    active_subscriptions: active_count,
    mrr_lite: Math.round(byTier.Lite * 100) / 100,
    mrr_pro: Math.round(byTier.Pro * 100) / 100,
    mrr_max: Math.round(byTier.Max * 100) / 100
  }
}];

